// From repository root: node evidence/road-workers/dispatch-calibration/check-compatibility.mjs [expected density]
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import vm from 'node:vm';

const util = readFileSync('js/util.js', 'utf8');
const sim = readFileSync('js/sim.js', 'utf8');
const wrapper = readFileSync('js/road-kernel.js', 'utf8');
const density = Number(process.argv[2] ?? 0.10);
assert.ok(density > 0 && density <= 1);

// Run the actual Blob generated by CarPool in a second JS realm. Messages clone or transfer
// their data just as in a Worker. Synchronous delivery keeps this a deterministic functional check.
function page({memory = 8, touch = false, fault} = {}) {
  const counts = {instances: 0, cloneFailures: 0};
  const context = {CM: {}, atob, navigator: {hardwareConcurrency: 12, deviceMemory: memory},
    matchMedia: () => ({matches: touch}), WebAssembly: fault === 'no-wasm' ? undefined : WebAssembly,
    Blob: class {constructor(parts) { this.source = parts.join(''); }},
    URL: {createObjectURL: blob => blob.source, revokeObjectURL() {}},
  };
  class Worker {
    constructor(source) {
      const Instance = new Proxy(WebAssembly.Instance, {construct(target, args) {
        counts.instances++;
        if (fault === 'instantiate') throw Error('test instance failure');
        return Reflect.construct(target, args);
      }});
      this.realm = {WebAssembly: {Instance}, onmessage: null,
        postMessage: (result, transfer) => this.onmessage({data: structuredClone(result, {transfer})})};
      vm.runInNewContext(source, this.realm);
    }
    postMessage(message, transfer = []) {
      if (message.type === 'graph' && message.kernel && fault === 'clone') {
        counts.cloneFailures++;
        throw new DOMException('test clone failure', 'DataCloneError');
      }
      this.realm.onmessage({data: structuredClone(message, {transfer})});
    }
    terminate() {}
  }
  if (fault !== 'no-worker') context.Worker = Worker;
  context.window = context;
  vm.createContext(context);
  vm.runInContext(util, context);
  vm.runInContext(wrapper, context);
  vm.runInContext(sim, context);
  return {CM: context.CM, context, counts};
}
const Z = 100;
const ints = Int32Array.from.bind(Int32Array);
const range = n => Array.from({length: n}, (_, i) => i);
// A directed diamond, an unreachable node, unequal distance for equal driving times,
// and multiple zones sharing access nodes. Use fractional km and demand to test typed rounding.
const graph = {id: 7, Z, nN: 5, nA: 4, outStart: ints([0, 2, 3, 4, 4, 4]),
  outArc: ints([0, 1, 2, 3]), arcTo: ints([1, 2, 3, 3]), arcFrom: ints([0, 0, 1, 2]),
  arcKm: Float64Array.of(0.1, 0.2, 0.3, 0.35), start: ints(range(Z + 1)), zones: ints(range(Z)),
  nodes: ints(range(Z).map(i => i % 5)), km: Float64Array.from(range(Z), i => i / 151),
  times: Float64Array.from(range(Z), i => i / 23)};
const time = Float32Array.of(1, 1, 1, 1);
function solve(p, entries, edgeTime = time) {
  const pool = p.CM.CarPool;
  assert.ok(pool.ready());
  const before = {...pool.stats};
  const block = {origins: Int32Array.of(0), tStart: Int32Array.of(0, entries),
    tDest: ints(range(entries)), dem: Float32Array.from(range(entries), i => (i + 1) / 7)};
  const req = pool.submit(graph, edgeTime, [block], () => true);
  assert.equal(req.failed, false);
  assert.equal(req.remaining, 0);
  const result = req.res[0];
  const deltas = {js: pool.stats.js - before.js, wasm: pool.stats.wasm - before.wasm};
  assert.equal(deltas.wasm + deltas.js, 1);
  return {result, wasm: deltas.wasm === 1};
}
function equalOutput(actual, expected) {
  for (const field of ['rowsT', 'rowsK', 'aux']) {
    const bytes = a => Buffer.from(a.buffer, a.byteOffset, a.byteLength);
    assert.deepEqual(bytes(actual[field]), bytes(expected[field]), field);
  }
}
const noWasm = page({fault: 'no-wasm'});
assert.equal(noWasm.CM.RoadKernel.module, null);
const good = page();
assert.ok(good.CM.RoadKernel.module instanceof WebAssembly.Module);
const boundary = Math.ceil(density * Z);
for (const entries of new Set([1, boundary - 1, boundary, Z])) {
  const actual = solve(good, entries);
  const expected = solve(noWasm, entries);
  assert.equal(expected.wasm, false);
  assert.equal(actual.wasm, entries >= boundary, 'dispatch for ' + entries + ' of ' + Z + ' destinations');
  equalOutput(actual.result, expected.result);
}
const full = solve(noWasm, Z).result;
assert.ok(full.aux.some(v => v > 0));
assert.equal(full.aux[3], 0, 'first of equal paths wins');
assert.ok(Number.isNaN(full.rowsT[4]), 'unreachable node');
for (const fault of ['clone', 'instantiate']) {
  const p = page({fault});
  for (let i = 0; i < 2; i++) {
    const result = solve(p, Z);
    assert.equal(result.wasm, false);
    equalOutput(result.result, full);
  }
  assert.equal(p.counts.instances, fault === 'instantiate' ? 1 : 0);
  assert.equal(p.counts.cloneFailures, fault === 'clone' ? 1 : 0);
}
// The compiled kernel rejects zero travel time. JS can process it without a negative cycle.
const invalidCost = Float32Array.of(0, 1, 1, 1);
const rejected = page();
const first = solve(rejected, Z, invalidCost);
assert.equal(first.wasm, false);
equalOutput(first.result, solve(noWasm, Z, invalidCost).result);
const following = solve(rejected, Z);
assert.equal(following.wasm, false);
equalOutput(following.result, full);
assert.equal(rejected.counts.instances, 1);

for (const [options, expected] of [[{}, [4, 2, 2]], [{touch:true}, [2, 1, 1]],
  [{memory:4}, [2, 1, 1]], [{memory:2}, [1, 0, 0]]]) {
  const {CM} = page(options);
  const pools = [CM.CarPool, CM.OdPool, CM.SkimPool];
  for (const pool of pools) pool.ready();
  assert.deepEqual(pools.map(pool => pool.list?.length ?? 0), expected);
}
// Run one normal Model.iterate period on the tutorial map, first without Worker, then in
// the production road pool. Keep mode/metro inline in both so only road dispatch varies.
function tutorialPeriod(fault) {
  const {context, CM} = page({fault});
  Object.assign(context, {performance, btoa, TextEncoder, TextDecoder, setTimeout, clearTimeout,
    localStorage: {getItem: () => null, setItem() {}, removeItem() {}}});
  const load = file => vm.runInContext(readFileSync(file, 'utf8'), context, {filename:file});
  for (const [,file] of readFileSync('index.html','utf8').matchAll(/<script src="([^"]+)"/g)) {
    load(file);
    if (file === 'js/save.js') break;
  }
  CM.UI = function() {};
  for (const name of ['settings','corp','fleet','screens']) load('js/'+name+'.js');
  CM.useMap('tutorial');
  const model = CM.Game.create({mode:'free', tutorial:true, seed:20000101}).model;
  CM.OdPool.off = CM.SkimPool.off = true;
  const pool = CM.CarPool;
  const before = pool.stats.wasm + pool.stats.js;
  const period = model.ctxs.wd.per[0];
  const gen = model.iterate(model.net, period, 0, {fullSkim:true, noSmooth:true});
  for (const value of gen) assert.notEqual(value, CM.SIM_WAIT);
  assert.equal(pool.off, fault === 'no-worker');
  assert.equal(pool.stats.wasm + pool.stats.js > before, fault !== 'no-worker');
  assert.ok(period.arcVol.some(value => value > 0), 'positive traffic after fallback allocation');
  return Object.fromEntries(Object.entries(period).filter(([,v]) => ArrayBuffer.isView(v))
    .map(([name,v]) => [name, Buffer.from(v.buffer,v.byteOffset,v.byteLength)]));
}
const direct = tutorialPeriod('no-worker');
const pooled = tutorialPeriod();
assert.ok(Object.keys(direct).length >= 20);
assert.deepEqual(direct, pooled);
console.log('PASS actual JS/WASM worker outputs, density boundaries, missing WASM, clone/instance/solve failure, planner and full no-Worker tutorial period ('
  + Object.keys(direct).length + ' typed arrays)');
